#include <cstddef>
#include <cstdint>
#include <cstdlib>

// clang++ -g -O1 -fsanitize=fuzzer,address fuzz_hi.cpp -o fuzz_hi
// ./fuzz_hi corpus/ -max_len=64 -dict=hi.dict
extern "C" int LLVMFuzzerTestOneInput(const uint8_t* data, size_t size) {
    if (size > 0 && data[0] == 'H')           // new branch → input kept
        if (size > 1 && data[1] == 'I')       // mutate the kept input
            if (size > 2 && data[2] == '!')
                std::abort();                 // found in ~4,000 runs
    return 0;                                 // -1: never add this input
}

#include <fuzzer/FuzzedDataProvider.h>

extern "C" int LLVMFuzzerTestOneInput(const uint8_t* data, size_t size) {
    FuzzedDataProvider fdp(data, size);
    int depth = fdp.ConsumeIntegralInRange(0, 16);   // typed values from raw bytes
    std::string text = fdp.ConsumeRemainingBytesAsString();

    auto doc = json::parse(text, depth);             // no exit(), no randomness
    if (doc) assert(json::parse(doc->dump(), depth) == doc);   // round-trip oracle
    return 0;
}
